<?php
namespace App\Services\Operations;
use App\Enums\RoomStatus;use App\Models\{HousekeepingTask,Room,Stay};use Illuminate\Support\Facades\DB;
class HousekeepingService{
 public function createCheckoutTask(Stay $stay,int $userId):HousekeepingTask{return HousekeepingTask::firstOrCreate(['stay_id'=>$stay->id,'type'=>'checkout_clean'],['property_id'=>$stay->property_id,'room_id'=>$stay->room_id,'status'=>'pending','priority'=>'high','due_at'=>now()->addHours(2),'created_by'=>$userId,'notes'=>'Automatic checkout cleaning task.']);}
 public function setStatus(HousekeepingTask $task,string $status,int $userId,?int $assignee=null,?string $notes=null):HousekeepingTask{return DB::transaction(function()use($task,$status,$userId,$assignee,$notes){$room=Room::query()->lockForUpdate()->findOrFail($task->room_id);$data=['status'=>$status];if($assignee)$data['assigned_to']=$assignee;if($notes!==null)$data['notes']=$notes;if($status==='assigned'&& !$task->assigned_to)$data['assigned_to']=$assignee?:$userId;if($status==='cleaning'){$data['started_at']=$task->started_at?:now();$room->update(['status'=>RoomStatus::Cleaning,'housekeeping_status'=>'cleaning']);}if($status==='clean'){$data['completed_at']=now();$room->update(['status'=>RoomStatus::Cleaning,'housekeeping_status'=>'clean']);}if($status==='inspected'){$data['inspected_at']=now();$data['inspected_by']=$userId;$room->update(['status'=>RoomStatus::Available,'housekeeping_status'=>'inspected']);}if($status==='cancelled' && $room->status===RoomStatus::Cleaning)$room->update(['status'=>RoomStatus::Dirty,'housekeeping_status'=>'dirty']);$task->update($data);return $task->fresh();});}
}
